import React, { useState } from 'react';
import '../styles/theme.css';

export default function Expenses() {
  const [formData, setFormData] = useState({
    category: 'Transportation & Freight',
    amount: '12500',
    paidTo: 'Shree Ji Transport',
    date: '2026-09-01',
    notes: 'Freight charges for Indore Mandi delivery'
  });
  const [successMsg, setSuccessMsg] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSuccessMsg(true);
    setTimeout(() => setSuccessMsg(false), 3000);
  };

  return (
    <div style={{ padding: '10px 20px', maxWidth: '900px', margin: '0 auto', fontFamily: 'Segoe UI, sans-serif' }}>
      
      {/* Header Section */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <div>
          <h2 style={{ color: '#1B4D3E', margin: 0, fontSize: '22px' }}>Record Expense & Utilities</h2>
          <p style={{ color: '#718096', fontSize: '13px', margin: '4px 0 0 0' }}>Manage daily operating expenses, transport, and Mandi overheads.</p>
        </div>
        {successMsg && (
          <div style={{ background: '#C6F6D5', color: '#22543D', padding: '8px 16px', borderRadius: '8px', fontSize: '13px', fontWeight: 'bold', border: '1px solid #9AE6B4' }}>
            ✅ Expense Saved Successfully!
          </div>
        )}
      </div>

      {/* Form Card */}
      <div style={{ background: '#FFF', padding: '30px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.05)', border: '1px solid #E2E8F0' }}>
        
        <form onSubmit={handleSubmit} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
          
          {/* Category */}
          <div style={{ gridColumn: 'span 2' }}>
            <label style={labelStyle}>Expense Category</label>
            <select name="category" value={formData.category} onChange={handleChange} style={inputStyle}>
              <option value="Transportation & Freight">Transportation & Freight</option>
              <option value="Labor & Hamali">Labor & Hamali</option>
              <option value="Godown Rent & Maintenance">Godown Rent & Maintenance</option>
              <option value="Electricity & Utilities">Electricity & Utilities</option>
              <option value="Office & Miscellaneous">Office & Miscellaneous</option>
            </select>
          </div>

          {/* Amount */}
          <div>
            <label style={labelStyle}>Amount (₹)</label>
            <input type="number" name="amount" value={formData.amount} onChange={handleChange} style={{ ...inputStyle, fontSize: '16px', fontWeight: 'bold', color: '#E53E3E' }} />
          </div>

          {/* Paid To */}
          <div>
            <label style={labelStyle}>Paid To / Vendor Name</label>
            <input type="text" name="paidTo" value={formData.paidTo} onChange={handleChange} style={inputStyle} />
          </div>

          {/* Date */}
          <div style={{ gridColumn: 'span 2' }}>
            <label style={labelStyle}>Date</label>
            <input type="date" name="date" value={formData.date} onChange={handleChange} style={inputStyle} />
          </div>

          {/* Notes */}
          <div style={{ gridColumn: 'span 2' }}>
            <label style={labelStyle}>Description / Notes</label>
            <textarea name="notes" rows="3" value={formData.notes} onChange={handleChange} style={{ ...inputStyle, resize: 'none' }} />
          </div>

          {/* Submit Button */}
          <div style={{ gridColumn: 'span 2', marginTop: '10px' }}>
            <button type="submit" style={btnStyle}>
              Save Expense Entry
            </button>
          </div>

        </form>

      </div>

    </div>
  );
}

const labelStyle = { display: 'block', fontSize: '12px', fontWeight: '600', color: '#4A5568', marginBottom: '6px' };
const inputStyle = { width: '100%', padding: '12px 14px', borderRadius: '8px', border: '1px solid #CBD5E0', background: '#F8FAFC', fontSize: '14px', boxSizing: 'border-box', outline: 'none' };
const btnStyle = { width: '100%', background: '#1B4D3E', color: '#FFF', padding: '14px', border: 'none', borderRadius: '8px', fontWeight: 'bold', fontSize: '15px', cursor: 'pointer', boxShadow: '0 4px 6px rgba(0,0,0,0.1)', transition: 'background 0.2s' };
